/* oxlint-disable camelcase */

export interface RawImageData {
  file_name: string;
  original_file_name: string;
  height: number;
  width: number;
}

export interface RawVideoData {
  file_output: {
    video: { url: string; format: string; quality: string }[];
    image: { url: string; height: number; width: number }[];
  };
  title: string;
}

export interface RawAudioData {
  file_output: {
    audio: { url: string; format: string; quality: string }[];
  };
}

export interface RawFileData {
  original_file_name: string;
  file_name: string;
  media_type: string;
  file_url: string;
  file_output?: {
    video?: { url: string; format: string; quality: string }[];
  };
}
export interface MediaManagerSDKError {
  error_code: number;
  error_description: string;
  error_info: {
    message: string;
    args?: any[]; // oxlint-disable-line @typescript-oxlint/no-explicit-any
    key: string;
  };
}

