import type { IconComponent } from '@wix/wix-ui-icons-common/core';
import { ChevronDownSmall } from '@wix/wix-ui-icons-common/lazy';
import React, { forwardRef } from 'react';

import { ToolbarButton } from './toolbar-button/toolbar-button.js';

type Props = {
  icon: IconComponent;
  onClick: (e: React.PointerEvent<HTMLButtonElement>) => void;
  tooltip: string;
  active: boolean;
  disabled?: boolean;
  dataHook?: string;
  ariaControlsId?: string;
  tabIndex?: number;
};

export const DropdownButton = forwardRef<HTMLButtonElement, Props>(
  ({ icon: Icon, dataHook, tooltip, onClick, active, disabled, ariaControlsId, tabIndex }, ref) => {
    return (
      <ToolbarButton
        ref={ref}
        tooltip={tooltip}
        onClick={onClick}
        active={active}
        disabled={disabled}
        prefix={Icon}
        suffix={ChevronDownSmall}
        dataHook={dataHook}
        aria-haspopup="true"
        aria-expanded={active}
        aria-controls={ariaControlsId}
        tabIndex={tabIndex}
      />
    );
  }
);

DropdownButton.displayName = 'DropdownButton';
